type Product = { id: string; name: string };
type Props = { products: Product[] };

function ShopScreen({ products }: Props) {
  return (
    <ScrollView>
      <Banner />
      <CategoryChips />
      <FlatList
        data={products}
        keyExtractor={(p) => p.id}
        renderItem={({ item }) => <ProductRow product={item} />}
      />
    </ScrollView>
  );
}

type Message = { id: string; text: string };
type RowProps = { message: Message };

function MessageRow({ message }: RowProps) {
  const [expanded, setExpanded] = useState(false);
  return (
    <Pressable onPress={() => setExpanded((e) => !e)}>
      <Text numberOfLines={expanded ? undefined : 2}>{message.text}</Text>
    </Pressable>
  );
}
function Inbox({ messages }: { messages: Message[] }) {
  return (
    <FlashList
      data={messages}
      keyExtractor={(m) => m.id}
      renderItem={({ item }) => <MessageRow message={item} />}
    />
  );
}

const ROW_HEIGHT = 64;
const SEPARATOR_HEIGHT = 1;
const Separator = () => <View style={{ height: SEPARATOR_HEIGHT }} />;

type Contact = { id: string; name: string };
type Props = { contacts: Contact[]; listRef: React.RefObject<FlatList<Contact> | null> };

function ContactList({ contacts, listRef }: Props) {
  return (
    <FlatList
      ref={listRef}
      data={contacts}
      keyExtractor={(c) => c.id}
      ItemSeparatorComponent={Separator}
      getItemLayout={(_, index) => ({ length: ROW_HEIGHT, offset: ROW_HEIGHT * index, index })}
      renderItem={({ item }) => <ContactRow contact={item} />}
    />
  );
}
